def sc(id, cur, n, titre, theme, jour, etape, niveau, lieu, equipe, cases, objectifs, message, contexte, roles, secouristes, evolution,
       attendus, observe, mat, securite, debrief, duree=DEB):
    return dict(id=id, cur=cur, n=n, titre=titre, theme=theme, jour=jour, etape=etape, niveau=niveau, duree=duree, lieu=lieu, equipe=equipe,
                cases=cases, checks=[], objectifs=objectifs, message=message, contexte=contexte, roles=roles, secouristes=secouristes,
                evolution=[list(x) for x in evolution], attendus=attendus, observe=observe, mat=mat, securite=securite, debrief=debrief)

def V(nom, brief, jeu, param, maq=''):
    return dict(t='Victime', nom=nom, brief=brief, jeu=jeu, param=param, maq=maq)

def T(nom, brief, jeu='', t='Tiers'):
    return dict(t=t, nom=nom, brief=brief, jeu=jeu, param=[], maq='')

